"""小学一到六年级的教师卡片。按各册目录写讲法，不收录课本原句。"""

from __future__ import annotations


def _unit(uid: str, grade: str, volume: str, title: str, aliases: list[str], teach: str, steps: list[str], guard: str, error: str) -> tuple[dict, dict]:
    chapter = {
        "id": uid,
        "grade": grade,
        "volume": volume,
        "title": title,
        "nodes": [uid],
        "intro": teach,
        "mindmap": steps,
        "guard": guard,
    }
    node = {
        "title": title,
        "chapter": uid,
        "aliases": aliases,
        "teach": teach,
        "mindmap": steps,
        "errors": [{"code": "calculation", "label": error}],
    }
    return chapter, node


