def _build() -> tuple[list[dict], dict[str, dict]]:
    chapters: list[dict] = []
    nodes: dict[str, dict] = {}
    for row in _ROWS:
        chapter, node = _unit(*row)
        chapters.append(chapter)
        nodes[chapter["id"]] = node
    return chapters, nodes


PRIMARY_CHAPTERS, PRIMARY_NODES = _build()
